  9→interface StageTrackerProps {
 10→  currentStage: HiringStage;
 11→  updatedAt?: string | null;
 12→  onStageChange: (stage: HiringStage) => void;
 13→  disabled?: boolean;
 14→}
 15→
 16→const STAGE_LABELS: Record<string, string> = {
 17→  applied: "Applied",
 18→  screened: "Screened",
 19→  interview: "Interview",
 20→  offer: "Offer",
 21→  hired: "Hired",
 22→};
 23→
 24→const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
 25→  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
 26→  const isRejected = currentStage === "rejected";
 27→
 28→  return (
 29→    <div className="flex items-center gap-2">
 30→      <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>
 31→
 32→      <div className="flex items-center gap-0 flex-1 min-w-0">
 33→        {STAGE_ORDER.map((stage, i) => {
 34→          const isCompleted = !isRejected && i < currentIndex;
 35→          const isCurrent = !isRejected && i === currentIndex;
 36→          const isUpcoming = isRejected || i > currentIndex;
 37→
 38→          return (
 39→            <div key={stage} className="flex items-center">
 40→              {/* Dot */}
 41→              <TooltipProvider delayDuration={200}>
 42→                <Tooltip>
 43→                  <TooltipTrigger asChild>
 44→                    <button
 45→                      disabled={disabled}
 46→                      onClick={(e) => {
 47→                        e.stopPropagation();
 48→                        onStageChange(stage);
 49→                      }}
 50→                      className={cn(
 51→                        "w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold transition-all shrink-0",
 52→                        "focus:outline-none focus:ring-2 focus:ring-primary/30",
 53→                        isCompleted && "bg-emerald-500 text-white",
 54→                        isCurrent && "bg-primary text-white ring-2 ring-primary/30",
 55→                        isUpcoming && "bg-muted border border-border text-muted-foreground",
 56→                        !disabled && "cursor-pointer hover:scale-110",
 57→                        disabled && "cursor-default"
 58→                      )}
 59→                    >
 60→                      {isCompleted ? "✓" : i + 1}
 61→                    </button>
 62→                  </TooltipTrigger>
 63→                  <TooltipContent className="text-xs">
 64→                    {isCompleted ? `${STAGE_LABELS[stage]} (done)` : isCurrent ? `${STAGE_LABELS[stage]} (current)` : `Move to ${STAGE_LABELS[stage]}`}
 65→                  </TooltipContent>
 66→                </Tooltip>
 67→              </TooltipProvider>
 68→
 69→              {/* Connector line */}
 70→              {i < STAGE_ORDER.length - 1 && (
 71→                <div
 72→                  className={cn(
 73→                    "h-0.5 w-6 sm:w-8 transition-all",
 74→                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
 75→                  )}
 76→                />
 77→              )}
 78→            </div>
 79→          );
 80→        })}
 81→      </div>
 82→
 83→      {/* Labels row - shown below on small screens, inline on larger */}
 84→      <div className="hidden sm:flex items-center gap-1">
 85→        {/* Reject button */}
 86→        <TooltipProvider delayDuration={200}>
 87→          <Tooltip>
 88→            <TooltipTrigger asChild>
 89→              <Button
 90→                variant="ghost"
 91→                size="icon"
 92→                disabled={disabled}
 93→                className={cn(
 94→                  "h-6 w-6",
 95→                  isRejected ? "text-destructive" : "text-muted-foreground/50 hover:text-destructive"
 96→                )}
 97→                onClick={(e) => {
 98→                  e.stopPropagation();
 99→                  onStageChange("rejected");
100→                }}
101→              >
102→                <XCircle className="h-3.5 w-3.5" />
103→              </Button>
104→            </TooltipTrigger>
105→            <TooltipContent className="text-xs">Reject candidate</TooltipContent>
106→          </Tooltip>
107→        </TooltipProvider>
108→      </div>
109→
110→      {/* Rejected badge */}
111→      {isRejected && (
112→        <Badge variant="destructive" className="text-[10px] shrink-0">Rejected</Badge>
113→      )}
114→
115→      {/* Updated timestamp */}
116→      {updatedAt && (() => {
117→        try {
118→          return (
119→            <span className="text-[10px] text-muted-foreground shrink-0 hidden sm:inline">
120→              Updated {format(new Date(updatedAt), "MMM d")}
121→            </span>
122→          );
123→        } catch {
124→          return null;
125→        }
126→      })()}
127→    </div>
128→  );
129→};
