 28→const getConfidenceBadge = (
 29→  avg: number
 30→): { label: string; variant: "default" | "secondary" | "destructive" | "outline" } => {
 31→  if (avg >= 75) return { label: "High", variant: "default" };
 32→  if (avg >= 45) return { label: "Medium", variant: "secondary" };
 33→  return { label: "Low", variant: "destructive" };
 34→};
