123→              </div>
124→              <Progress value={avgConfidence} className="h-2" />
125→            </div>
126→
127→            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
128→              {/* Per-Dimension scores */}
129→              {dimensions.length > 0 && (
130→                <div className="space-y-3">
131→                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
132→                    Scoring Dimensions
133→                  </p>
134→                  <div className="space-y-2.5">
135→                    {dimensions.map((dim) => (
136→                      <div key={dim.name} className="space-y-1">
137→                        <div className="flex items-center justify-between">
138→                          <span className="text-xs font-medium text-foreground">
139→                            {formatDimensionName(dim.name)}
140→                          </span>
141→                          <span
142→                            className={cn(
143→                              "text-xs font-semibold tabular-nums",
144→                              dim.avg >= 70
145→                                ? "text-score-skills"
146→                                : dim.avg >= 40
147→                                ? "text-warning"
148→                                : "text-destructive"
