187→                        axisLine={false}
188→                        tickLine={false}
189→                      />
190→                      <YAxis
191→                        allowDecimals={false}
192→                        tick={{ fontSize: 10, fill: "hsl(var(--muted-foreground))" }}
193→                        axisLine={false}
194→                        tickLine={false}
195→                        width={28}
196→                      />
197→                      <Tooltip
198→                        cursor={{ fill: "hsl(var(--muted))" }}
199→                        contentStyle={{
200→                          background: "hsl(var(--card))",
201→                          border: "1px solid hsl(var(--border))",
202→                          borderRadius: "6px",
203→                          fontSize: "12px",
204→                          padding: "6px 10px",
205→                        }}
206→                        formatter={(value: number, _name: string, props: any) => [
207→                          `${value} candidate${value !== 1 ? "s" : ""}`,
208→                          props.payload?.range ?? "",
209→                        ]}
210→                        labelFormatter={(label) => label}
211→                      />
212→                      <Bar
213→                        dataKey="count"
214→                        radius={[4, 4, 0, 0]}
215→                        fill="hsl(var(--primary))"
216→                        maxBarSize={48}
217→                      />
218→                    </BarChart>
219→                  </ResponsiveContainer>
220→                </div>
221→                {/* Bucket breakdown as compact text */}
222→                <div className="grid grid-cols-2 gap-1.5">
223→                  {buckets.map((b) => (
224→                    <div
225→                      key={b.label}
226→                      className="flex items-center justify-between rounded-md bg-muted/50 px-2.5 py-1.5"
227→                    >
228→                      <span className="text-[11px] text-muted-foreground">{b.label}</span>
229→                      <span className="text-[11px] font-semibold tabular-nums text-foreground">
