 49→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 50→
 51→const JobDetailView = ({
 52→  selectedJobId,
 53→  selectedJob,
 54→  results,
 55→  setResults,
 56→  existingResumes,
 57→  setExistingResumes,
 58→  onJobCreated,
 59→  onAuthRequired,
 60→  onJobUpdated,
 61→  isAuthenticated = true,
 62→}: JobDetailViewProps) => {
 63→  const { user, profile, refreshProfile } = useAuth();
 64→  const { data: config } = usePlatformConfig();
 65→
 66→  const [jobDescription, setJobDescription] = useState("");
 67→  const [files, setFiles] = useState<UploadedFile[]>([]);
 68→  const [ranking, setRanking] = useState(false);
 69→  const [rankingProgress, setRankingProgress] = useState(0);
 70→  const [scoredCount, setScoredCount] = useState(0);
 71→  const [totalToScore, setTotalToScore] = useState(0);
 72→  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
 73→  const [dragOver, setDragOver] = useState(false);
 74→  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
 75→  const [validationErrors, setValidationErrors] = useState<string[]>([]);
 76→  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
 77→  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
 78→  const [deleting, setDeleting] = useState(false);
 79→  const [analyzingJd, setAnalyzingJd] = useState(false);
 80→  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
 81→  const [showArchived, setShowArchived] = useState(false);
 82→  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
 83→
 84→  const resultsRef = useRef<HTMLDivElement>(null);
 85→  const rankingFilesRef = useRef<Set<string>>(new Set());
 86→  const maxResumes = config?.max_resumes_per_job ?? 10;
 87→  const maxFileSizeMb = config?.max_file_size_mb ?? 5;
 88→
 89→  const isNewJobMode = selectedJobId === null;
 90→  const isExistingJob = selectedJobId !== null && selectedJob !== null;
 91→
 92→  // Hiring Stage Tracker
 93→  const { data: stages } = useStages(selectedJobId);
 94→  const updateStageMutation = useUpdateStage();
 95→  const stageSummary = useStageSummary(selectedJobId);
 96→  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));
 97→
 98→  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
 99→    if (!selectedJobId) return;
100→    const current = stageMap.get(resumeId);
101→    updateStageMutation.mutate({
102→      resumeId,
103→      jobId: selectedJobId,
104→      newStage,
105→      currentStage: current?.stage,
106→    });
107→  };
108→
109→  const formatCandidateName = (filename: string) => {
110→    const name = filename.replace(/\.\w+$/, "");
111→    if (UUID_REGEX.test(name)) return `Candidate`;
112→    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
113→  };
114→
115→  // Merge unranked resumes
116→  const resultResumeIds = new Set(results.map((r) => r.resume_id));
117→  const pendingResumes: Result[] = existingResumes
118→    .filter((r) => !resultResumeIds.has(r.id))
119→    .map((r) => ({
120→      id: `pending-${r.id}`,
121→      resume_id: r.id,
122→      overall_score: 0,
123→      missing_skills: [], summary: null, interview_questions: null,
124→      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
125→      pending: true,
126→    }));
127→  const allResults = [...results, ...pendingResumes];
128→
129→  // Selection helpers
130→  const toggleSelectResume = (resumeId: string) => {
131→    setSelectedResumes((prev) => {
132→      const next = new Set(prev);
133→      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
