144→    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
145→    await supabase.from("results").delete().eq("resume_id", resumeId);
146→    await supabase.from("resumes").delete().eq("id", resumeId);
147→    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
148→    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
149→    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
