163→      }
164→    } catch { toast.error("Failed to delete"); }
165→    finally { setDeleting(false); setDeleteConfirm(null); }
166→  };
167→
168→  // File handling
169→  const handleFileDrop = useCallback((e: React.DragEvent) => {
170→    e.preventDefault(); setDragOver(false);
171→    const dropped = Array.from(e.dataTransfer.files).filter(
172→      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
173→    );
174→    addFiles(dropped);
175→  }, [files, maxResumes, maxFileSizeMb]);
176→
177→  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
178→    if (e.target.files) addFiles(Array.from(e.target.files));
179→  };
180→
181→  const addFiles = (newFiles: File[]) => {
182→    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
183→    const valid = newFiles.filter((f) => {
184→      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
185→      return true;
186→    });
187→    const remaining = maxResumes - currentCount;
188→    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
189→    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
190→    setFiles((prev) => [...prev, ...toAdd]);
191→  };
192→
193→  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
194→  const toggleRow = (id: string) => {
