201→
202→  const validate = (): string[] => {
203→    const errors: string[] = [];
204→    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
205→    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
206→    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
207→    const splitTotal = (profile?.subscription_credits ?? 0) + (profile?.topup_credits ?? 0);
208→    const totalCredits = splitTotal > 0 ? splitTotal : (profile?.credits ?? 0);
209→    if (user && totalCredits < Math.min(filesToCheck.length, 20)) {
210→      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, 20)} but have ${totalCredits}.`);
211→    }
212→    return errors;
213→  };
214→
215→  // ── Analyze JD ──────────────────────────────────────────────
216→  const analyzeJd = async (jobId: string) => {
217→    setAnalyzingJd(true);
218→    try {
219→      const response = await fetch(
220→        `https://zkzontawprihrzpayeam.supabase.co/functions/v1/analyze-jd`,
221→        {
222→          method: "POST",
223→          headers: {
224→            "Content-Type": "application/json",
225→            Authorization: `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`,
226→          },
227→          body: JSON.stringify({ job_id: jobId }),
228→        }
229→      );
230→      if (!response.ok) {
231→        const err = await response.json().catch(() => ({}));
232→        throw new Error(err.error || "JD analysis failed");
233→      }
234→      const data = await response.json();
235→      if (onJobUpdated) {
236→        onJobUpdated(jobId, {
237→          jd_analysis_json: data.jd_analysis,
